[WMI, Dynamic, Provider("WmiProv"), Locale("MS\0x409"), Description("LENOVO CAPABILITY DATA 00"), guid("{362a3afe-3d96-4665-8530-96dad5bb300e}")] class LENOVO_CAPABILITY_DATA_00 { [key, read] string InstanceName; [read] boolean Active;
[WmiDataId(1), read, Description(" IDs.")] uint32 IDs;
