"""Extract ACPI-WMI Binary-MOF (BMF/BMOF) buffers.

Each Lenovo WMI BMOF is stored in AML as a Buffer whose raw bytes are verbatim
in the .aml file, so a byte scan for the BMF signature is sufficient.  Header
(LE u32): 0x00 signature 0x424D4F46, 0x04 version=1, 0x08 comp_size,
0x0C raw_size; file size = 16 + comp_size.

Writes <table>_<Name>_<offset>.bmof to 20-acpi/mof/raw/ and also tries to
read the sysfs BMF via wmi-bmof (/sys/bus/wmi/devices/05901221-*/bmof).
Reference implementation of the container: github.com/pali/bmfdec (bmfdec.c).
"""
import os, glob, struct

W = "/home/user/Downloads/lenovo-camera-switch-re"
AML = os.path.join(W, "20-acpi", "aml")
OUT = os.path.join(W, "20-acpi", "mof", "raw")
SYS = "/sys/bus/wmi/devices"
HDR = bytes([0x46,0x4F,0x4D,0x42,0x01,0x00,0x00,0x00])

def namestring(data, off, back=64):
    for p in range(off-5, max(-1, off-back)-1, -1):
        if data[p] == 0x08:                       # AML NameOp
            nm = data[p+1:p+5]
            if all(0x30 <= c <= 0x39 or 0x41 <= c <= 0x5A or c == 0x5F for c in nm):
                return nm.decode("ascii")
    return None

def main():
    os.makedirs(OUT, exist_ok=True)
    man = []
    for path in sorted(glob.glob(os.path.join(AML, "*.aml"))):
        data = open(path, "rb").read()
        tbl = os.path.basename(path)[:-4]
        i = 0
        while True:
            i = data.find(HDR, i)
            if i < 0 or i + 16 > len(data):
                break
            comp, raw = struct.unpack_from("<II", data, i + 8)
            total = 16 + comp
            if i + total <= len(data) and 0 < raw <= 0x1000000:
                nm = namestring(data, i) or "buf"
                fn = "%s_%s_%06X.bmof" % (tbl, nm, i)
                open(os.path.join(OUT, fn), "wb").write(data[i:i+total])
                man.append("%-28s table=%s aml_off=0x%06X comp=%d raw=%d" % (fn, tbl, i, comp, raw))
            i += 4
    for dev in sorted(glob.glob(os.path.join(SYS, "05901221-*"))):
        try:
            blob = open(os.path.join(dev, "bmof"), "rb").read()
        except PermissionError:
            man.append("SKIP sysfs %s/bmof: EACCES (root-only)" % dev)
            continue
        except OSError as e:
            man.append("SKIP sysfs %s/bmof: %s" % (dev, e))
            continue
        fn = "sysfs_%s.bmof" % os.path.basename(dev)
        open(os.path.join(OUT, fn), "wb").write(blob)
        man.append("%-28s sysfs=%s len=%d" % (fn, dev, len(blob)))
    open(os.path.join(OUT, "MANIFEST.txt"), "w").write("\n".join(man) + "\n")
    print("\n".join(man))

if __name__ == "__main__":
    main()
