#!/usr/bin/env python3
# Extract BMF/BMOF buffers (Lenovo ACPI-WMI Binary MOF) from the AML tables.
# Container layout (u32 LE, verified): 0x00 'FOMB'(=0x424D4F46) 0x04 ver=1
# 0x08 comp_size (DS-01 stream length)  0x0C raw_size (decompressed length)
# total file size = 16 + comp_size.  The bytes sit verbatim inside the AML
# Buffer object, so a plain byte scan of the .aml finds them.
import os, glob, struct
W="/home/user/Downloads/lenovo-camera-switch-re"
AML=os.path.join(W,"20-acpi","aml"); OUT=os.path.join(W,"20-acpi","mof","raw")
SYSFS="/sys/bus/wmi/devices"; HDR=b"\x46\x4f\x4d\x42\x01\x00\x00\x00"

def aml_name(d,off):
    # AML NameString is 4 chars right after 0x08 (NameOp); scan backwards
    for p in range(off-1,max(-1,off-64),-1):
        if d[p]==0x08:
            nm=d[p+1:p+5]
            if all((0x30<=c<=0x39) or (0x41<=c<=0x5a) or c==0x5f for c in nm):
                return nm.decode()
    return "buf"

def main():
    os.makedirs(OUT,exist_ok=True); man=[]
    for path in sorted(glob.glob(os.path.join(AML,"*.aml"))):
        d=open(path,"rb").read(); tab=os.path.basename(path)[:-4]; i=0
        while True:
            i=d.find(HDR,i)
            if i<0 or i+16>len(d): break
            comp,raw=struct.unpack_from("<II",d,i+8); tot=16+comp
            if i+tot<=len(d) and 0<raw<=0x4000000:
                nm=aml_name(d,i); fn="%s_%s_%06X.bmof"%(tab,nm,i)
                open(os.path.join(OUT,fn),"wb").write(d[i:i+tot])
                man.append("%-28s off=0x%06X name=%-4s comp=%d raw=%d"%(fn,i,nm,comp,raw))
            i+=4
    for dev in sorted(glob.glob(os.path.join(SYSFS,"05901221-*"))):
        p=os.path.join(dev,"bmof")
        try: b=open(p,"rb").read()
        except PermissionError:
            man.append("SKIP sysfs %s: EACCES (root-only)"%p); continue
        except OSError as e:
            man.append("SKIP sysfs %s: %s"%(p,e)); continue
        fn="sysfs_%s.bmof"%os.path.basename(dev)
        open(os.path.join(OUT,fn),"wb").write(b)
        man.append("%-28s sysfs %s len=%d"%(fn,p,len(b)))
    open(os.path.join(OUT,"MANIFEST.txt"),"w").write("\n".join(man)+"\n")
    print("\n".join(man))

if __name__=="__main__": main()

