        else: b.pb+=11; r=rep(((u>>3)&255)+64)
        if r or not(len(out)<lout and (b.pd<b.pe or (b.pd==b.pe and b.pb<16))): break
    if r<0: raise DsErr("ds01 error %d"%r)
    u=b.rdn(3)
    if u==7: u=b.rdn(12)+320
    if u!=0x113f: raise DsErr("final sync missing")
    return bytes(out)

class BmofErr(Exception): pass
class Bmof:
    def __init__(s,d): s.d=d; s.second=None
    def u32(s,o): return struct.unpack_from("<I",s.d,o)[0]
    def i32(s,o): return struct.unpack_from("<i",s.d,o)[0]
    def st(s,o,n):
        r=s.d[o:o+n]; c=[chr(r[i]|(r[i+1]<<8)) for i in range(0,len(r)-1,2)]
        return "".join(c).split("\0",1)[0]
    def flav(s,q):
        if not s.second: return (0,0,0,0)
        base,cnt=s.second
        for i in range(cnt):
            p=base+4+8*i
            if s.u32(p)==q:
                f=s.u32(p+4); return (f&1,f&2,f&0x10,f&0x80)
        return (0,0,0,0)
    def qual(s,o,size):
        if size<16: raise BmofErr("qual short")
        t=s.u32(o+4); ql=s.u32(o+12)
        if 16+ql>size: raise BmofErr("qual len")
        nm=s.st(o+16,ql); val=None
        if t==0x0B: val=True if (16+4+ql>size or s.u32(o+16+ql)) else False
        elif t==0x03: val=s.i32(o+16+ql)
        elif t==0x08: val=s.st(o+16+ql,size-16-ql)
        elif t==0x2008: val="ValueMap"
