        t=s.u32(o+4); arr=t>>8; base=t&0xff
        if arr not in (0,0x20): return {"name":"?type0x%x"%t,"unknown":1}
        if s.u32(o+8): raise BmofErr("var unk")
        ln=s.u32(o+16); sl=s.u32(o+12)
        nm=s.st(o+20, sl if sl!=0xFFFFFFFF else ln)
        p=o+20+ln; qc=s.u32(p+4); tmp=p+8; qs=[]; obj=None; amax=None
        for i in range(qc):
            l2=s.u32(tmp); q=s.qual(tmp,l2)
            if q["name"]=="CIMTYPE" and q["type"]==0x08:
                v=q["value"]; obj=v[7:] if v.startswith("object:") else None
                if obj is None: base=None
            elif q["name"]=="MAX" and q["type"]==0x03 and arr: amax=q["value"]
            else: qs.append(q)
            tmp+=l2
        if base==0x0D: ty=obj or "object"
        elif base is None: ty="?"
        else: ty=BASIC.get(base,"?0x%x"%base)
        return {"name":nm,"type":ty,"array":bool(arr),"amax":amax,"qualifiers":qs}
    def prop(s,o,size,out):
        ln=s.u32(o)
        if ln==0 or size<ln or s.u32(o+8) or s.u32(o+16)!=0xFFFFFFFF: return
        t=s.u32(o+4); sl=s.u32(o+12); nm=s.st(o+20,sl)
        if t==0x08:
            v=s.st(o+20+sl,size-20-sl)
