        else:
            tmp=o; ln1=0
        c2=s.u32(tmp+4); tmp+=8
        for i in range(c2):
            l=s.u32(tmp)
            if s.u32(tmp+16)==0xFFFFFFFF: s.prop(tmp,l,out)
            else: out["variables"].append(s.var(tmp,l))
            tmp+=l
        while tmp!=o+size:
            l=s.u32(tmp); s.prop(tmp,l,out); tmp+=l
        return out
    def method(s,o,size):
        if s.u32(o+4) not in (0,0x200D): return {"name":"?m"+hex(s.u32(o+4)),"qualifiers":[]}
        nl=s.u32(o+12)
        if nl==0xFFFFFFFF: nl=s.u32(o+16)
        tot=s.u32(o+16); nm=s.st(o+20,nl); p=o+20+tot
        qc=s.u32(p+4); tmp=p+8; qs=[]
        for i in range(qc):
            l=s.u32(tmp); qs.append(s.qual(tmp,l)); tmp+=l
        return {"name":nm,"qualifiers":qs,"params":tot>nl}
    def klass(s,o,size):
        if s.u32(o+4) or size<20: return {"name":None}
        ln1=s.u32(o+8); ln=s.u32(o+12)
        if s.u32(o+16): return {"name":None}
        out=s.cdata(o+20,ln,ln1,True); p=o+20+ln; rem=size-20-ln
        if rem>=8:
            mcnt=s.u32(p+4); q=p+8
            for i in range(mcnt):
                l=s.u32(q); out["methods"].append(s.method(q,l)); q+=l
        return out
    def parse(s):
        d=s.d
        if len(d)<8 or s.u32(0)!=MAGIC: raise BmofErr("bad bmof magic")
        ln=s.u32(4)
        if ln<len(d):
            if d[ln:ln+16]!=b"BMOFQUALFLAVOR11": raise BmofErr("no second magic")
            s.second=(ln+16,s.u32(ln+16))
        cnt=s.u32(8); tmp=12; cls=[]
        for i in range(cnt):
            l=s.u32(tmp); cls.append(s.klass(tmp,l)); tmp+=l
        return cls

def fq(q):
    s=q["name"]; t=q["type"]
    if t==0x03: s+="(%d)"%q["value"]
    elif t==0x08: s+='("%s")'%q["value"]
    elif t==0x0B and q["value"] is False: s+="(FALSE)"
    fl=[n for n,b in zip(("ToInstance","ToSubclass","DisableOverride","Amended"),q["fl"]) if b]
    return s+(" : "+" ".join(fl) if fl else "")
def fqs(qs): return ("["+", ".join(fq(q) for q in qs)+"] ") if qs else ""
def fv(v):
    if v.get("unknown"): return "/* %s */"%v["name"]
    ty=v["type"]+(("[%s]"%("" if v.get("amax") is None else v["amax"])) if v.get("array") else "")
    return fqs(v["qualifiers"])+("%s %s;"%(ty,v["name"]))
def render(cls):
    L=[]
    for c in cls:
        if not c.get("name"): continue
        if c.get("qualifiers"): L.append(fqs(c["qualifiers"]).rstrip())
        L.append("class "+c["name"]+((" : "+c["superclass"]) if c.get("superclass") else "")+"\n{")
        for v in c.get("variables",[]): L.append("  "+fv(v))
        for m in c.get("methods",[]): L.append("  %svoid %s(%s);"%(fqs(m["qualifiers"]),m["name"],"..." if m.get("params") else ""))
        L.append("};\n")
    return "\n".join(L)+"\n"
def strings(d):
    L=["/* UTF-16LE strings in decompressed BMF (names survive even if parse fails) */"]; i=0; n=len(d)
    while i+1<n:
        if d[i+1]==0 and 32<=d[i]<127:
            j=i; s=[]
            while j+1<n and d[j+1]==0 and 32<=d[j]<127: s.append(chr(d[j])); j+=2
            if len(s)>=3: L.append("%06X: %s"%(i,"".join(s))); i=j; continue
        i+=1
    return "\n".join(L)+"\n"
def main():
    ap=argparse.ArgumentParser(); ap.add_argument("file"); ap.add_argument("-o","--output")
    ap.add_argument("--dump-bmf"); ap.add_argument("--strings",action="store_true")
    a=ap.parse_args(); d=open(a.file,"rb").read()
    if d[:4]==b"FOMB":
        mg,ver,comp,raw=struct.unpack_from("<IIII",d,0)
        if ver!=1 or comp!=len(d)-16: raise SystemExit("bad BMF header")
        data=ds01(d[16:16+comp],comp,raw)
    else: data=d
    if a.dump_bmf: open(a.dump_bmf,"wb").write(data)
    txt=None
    if not a.strings:
        try: txt=render(Bmof(data).parse())
        except Exception as e: sys.stderr.write("parse failed (%s); string dump follows\n"%e)
    if txt is None: txt=strings(data)
    if a.output: open(a.output,"w").write(txt)
    else: sys.stdout.write(txt)
if __name__=="__main__": main()

